    script.src = 'AbyssAudio.js?t=' + Date.now();
    script.async = true;
    script.onload = function() {
      console.log('[音效] AbyssAudio.js 预加载完成');
    };
    script.onerror = function() {
      console.warn('[音效] AbyssAudio.js 预加载失败');
    };
    document.head.appendChild(script);
  }
})();

