=== shouldTakeOver() 实现 + MODE_TAG 定义 ===
行 55: var MODE_TAG = 'classic2d';
行 106: function shouldTakeOver() {
95:     try {
96:       if (global.location && /[?&]classic2d=0(&|$)/.test(global.location.search)) return false;
97:       if (global.localStorage && global.localStorage.getItem(DISABLE_KEY) === '0') return false;
98:     } catch (e) { /* 无痕模式等：按启用处理 */ }
99:     return true;
100:   }
101: 
102:   /**
103:    * 现在该不该由宿主管画面
104:    * 选英雄 / 选增益 / 开始界面仍归内核 DOM；一旦进了房间就交给 2D。
105:    */
106:   function shouldTakeOver() {
107:     var s = S();
108:     if (!s || !s.hero) return false;
109:     if (s.gameOver) return false;
110:     // ⚠️ 这里**不能**再判 state.trial.active：试炼的代码已经删了，但 state.trial 是
111:     //    **存档里的纯数据**，loadGame 的 Object.assign 会把它带回来 ——
112:     //    一份「试炼进行中」的旧档会让本函数永远返回 false，玩家在两台设备上都会
113:     //    一路回退到文字模式（实测就是这么撞到的）。
114:     if (s.mode === 'heroSelect' || s.mode === 'bonusSelect' || s.mode === 'start') return false;
115:     if (s.mode === 'gameover' || s.mode === 'finished') return false;
116:     if (!s.currentRoom) return false;   // 还没进第一间房
117:     return true;
118:   }
119: 
120:   function active() {
121:     if (!enabled() || unavailable) return false;
122:     return running && booted;
123:   }
124: 
125:   /* ============================================================
126:      画布显隐
127:      ------------------------------------------------------------
128:      #trial2DStage 在 .app-shell 之内（主界面.html:802），所以不能靠隐藏外壳来
129:      露出画布 —— 反过来做：让画布（全屏 fixed 覆盖层）盖住 DOM 游戏区。
130:      这条路径与试炼模式完全一致，样式复用 .trial2d-stage，不新增 CSS 约定。
131:      ============================================================ */
132:   /**
133:    * 画布显隐
134:    * ------------------------------------------------------------
135:    * ⚠️ #trial2DStage 在 #trialScreen 内部（主界面.html:802 在 756 之后），
136:    *    而 #trialScreen 是 `.hidden`（opacity/scale，不是 display:none）——
137:    *    试炼未激活时它的高度会塌掉，Phaser RESIZE 跟着父容器走，画布实测只剩
138:    *    1279×214（而 --trial2d-vh 是 797px）。后果不是"看不见"，而是
139:    *    画内面板在小画布上算不出卡片、奖励三选一直接不弹（静默失败，极难排查）。
140:    *    所以这里**不走 CSS**：直接把 stage 钉成全屏 fixed，退出时清掉 inline style
141:    *    还给试炼模式的原有 CSS（试炼那边的行为一个字节都没动）。
142:    */
