    <div class="trial2d-boot-spinner"></div>
    <div class="trial2d-boot-title">正在启动 2D 实时战斗…</div>
    <div class="trial2d-boot-sub">首次进入需要下载 2D 战斗引擎（约 1.5 MB），下完就会缓存，之后不再等待。</div>
  </div>

  <!-- ============================================================
       2D 引擎按需加载器（阶段3优化）
       ------------------------------------------------------------
       首屏只加载「文字界面」所需的 主程序.js + 主样式.css + AbyssAudio.js
       （合计 417 KB）；phaser / 角色形象 / 战斗2D / 经典2D 这四件套（1467 KB）
       推迟到玩家真正要玩时再下载 —— 按 Netlify 的 30 KB/s 算，首屏从 22.5 秒
       降到约 4 秒。

       ⚠️ 必须串行加载，不能并行：
          battle2D.js 顶层写着 `class BattleScene extends Phaser.Scene`，
          这是脚本**解析时**就求值的 —— phaser.min.js 没先执行完，
          战斗2D.js 会直接抛 ReferenceError。所以下面用 reduce 串成一条链。

       接口（供 主程序.js 调用）：
         __加载2D引擎()    → Promise；开始加载或复用进行中的加载
         __2D引擎已就绪()  → boolean
         __确保2D引擎(cb)  → 引擎已就绪时**同步**回调（行为与原代码完全一致）；
                             未就绪时显示等待提示，加载完再回调；
                             加载失败也回调 → 自动降级走文字界面，不卡死。
       ============================================================ -->
  <script>
  (function () {
    'use strict';

    var FILES = [
      'vendor/phaser.min.js?v=20250907p',
      '角色形象.js?v=20250910r2',
      '战斗2D.js?v=202610210',
      '经典2D.js?v=202610220'
    ];

    var 加载中 = null;      // 进行中的 Promise（复用，避免重复下载）
    var 已就绪 = false;
    var 加载失败 = null;

    function 提示(show) {
      var el = document.getElementById('lazy2DBootHint');
      if (!el) return;
      el.classList.toggle('hidden', !show);
      if (show) {
        var sp = el.querySelector('.trial2d-boot-spinner');
        if (sp) sp.style.animationPlayState = 'running';
      }
    }

    function 载入一个(src) {
      return new Promise(function (resolve) {
        var s = document.createElement('script');
        s.src = src;
        s.async = false;          // 保持插入顺序
        s.onload = function () { resolve(true); };
        s.onerror = function () {
          console.error('[2D加载器] 脚本下载失败：' + src);
          resolve(false);          // 不 reject：让调用方拿回控制权去降级
        };
        document.head.appendChild(s);
      });
    }

    window.__加载2D引擎 = function () {
      if (加载中) return 加载中;
      加载中 = FILES.reduce(function (chain, src) {
        return chain.then(function (ok) {
          if (ok === false) return false;      // 前面挂了，后面不再硬试
          return 载入一个(src);
        });
      }, Promise.resolve(true)).then(function (ok) {
        已就绪 = ok !== false && !!window.经典2D;
        if (!已就绪) {
          加载失败 = '脚本未能全部加载';
          加载中 = null;                        // 允许以后重试
          console.warn('[2D加载器] 2D 引擎未就绪，本次将使用文字界面。');
        } else {
          console.log('[2D加载器] 2D 引擎就绪。');
        }
        return 已就绪;
      });
      return 加载中;
    };

    window.__2D引擎已就绪 = function () { return 已就绪; };

    /**
     * 需要 2D 时调用。
     * 已就绪 → 同步回调，调用方的行为与优化前逐字节一致。
     * 未就绪 → 显示提示、等下载完、再回调；失败也会回调（降级文字界面）。
     */
    window.__确保2D引擎 = function (cb) {
      if (typeof cb !== 'function') return;
      if (已就绪) { cb(); return; }

      提示(true);
      window.__加载2D引擎().then(function () {
        提示(false);
        try {
          cb();
        } catch (e) {
          console.error('[2D加载器] 回调执行出错：', e);
        }
      });
    };
  })();
  </script>
</body>
</html>
```

等等，有个问题：`s.async = false` 对动态创建的 script 意味着"按插入顺序执行"，但我们已经是串行加载（一个接一个），所以其实不需要。而且 `async = false` 对动态脚本是"有序执行"（类似 defer），会等前面的。这没坏处。

不过因为我们严格控制了串行（前一个 onload 后才插入下一个），所以 async 设置无所谓。保留 `async = false` 也无害。

另一个问题：**如果 `window.经典2D` 已存在（比如玩家在 2D 已经加载后），`__加载2D引擎` 会重复加载吗？** 不会，因为 `加载中` 会被缓存。

但如果页面加载时 经典2D 已经存在（不可能，因为我们移除了 script 标签），那也没问题。

**重要**：`__确保2D引擎` 在 `已就绪` 为 true 时同步回调 ✓

还有一个细节：**如果加载失败，`加载中` 被设为 null，那 `__确保2D引擎` 的 `.then` 还是会执行**（因为我用的是 `.then` 而不是 `.then(ok, fail)`，且 `__加载2D引擎` 内部不 reject）。✓ 好。

但有个 bug：如果加载失败后玩家再次触发 `__确保2D引擎`，会重新尝试加载（因为 `加载中` 被重置）。这是好事（可重试）。但 `提示(true)` 会再次显示。合理。

另一个边界：如果 `__加载2D引擎` 被调用两次（一次是预载，一次是 `__确保2D引擎`），第二次会复用 `加载中`。✓

