{"script": "(() => {
  const q = (s) => document.querySelector(s);
  const vis = (el) => {
    if (!el) return '不存在';
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden' || cs.opacity === '0') return '隐藏';
    return r.width > 0 && r.height > 0 ? `可见 ${Math.round(r.width)}x${Math.round(r.height)}` : '尺寸为0';
  };
  const fx = q('#startFxCanvas');
  return {
    开始界面: vis(q('#startScreen')),
    开始按钮: vis(q('#startGameBtn')),
    标题文字: q('.start-title') ? q('.start-title').textContent.trim() : '缺失',
    副标题: q('.start-subtitle') ? q('.start-subtitle').textContent.trim() : '缺失',
    版本号: q('.start-version') ? q('.start-version').textContent.trim() : '缺失',
    特效画布: vis(fx),
    特效画布尺寸: fx ? fx.width + 'x' + fx.height : '-',
    特效引擎已初始化: fx ? !!fx._abyssFxInited : '-',
