    星星层: vis(q('.stars-layer')),
    侧边栏: vis(q('#sidebar')),
    音频引擎: typeof window.AbyssAudio,
    游戏是否已初始化: !!window._gameInitialized,
    body滚动: getComputedStyle(document.body).overflow
  };
})()"}

