=== CSS 中所有 .hidden 规则 ===
行 402: .modal.hidden { display: none; }
行 1398: .custom-difficulty-panel.hidden { display: none; }
行 1638: .custom-difficulty-warning.hidden { display: none !important; }
行 2016: .start-screen.hidden {
行 2987: .start-screen.hidden {
行 5528: .trial2d-stage.hidden {
行 5580: .trial2d-fallback.hidden {
行 5675: .trial2d-rotate-hint.hidden {
行 5704: .trial2d-layout-bar.hidden {
行 6122: .trial2d-io-panel.hidden {
行 6188: /* 导出 / 导入两种模式靠 hidden 类切换按钮。页面上并没有全局的 .hidden 规则
行 6189: （各处都是「父选择器 + .hidden」成对写的），所以这里必须显式声明 ——
行 6191: .t2d-io-btns .t2d-lb-btn.hidden {
行 6263: .trial2d-boot.hidden {
行 6546: .trial2d-fallback-standalone.hidden { display: none; }

=== 确认 CSS 文件从未被本次改动触碰（对比备份时间）===

Name     LastWriteTime         KB
----     -------------         --
主样式.css  2026/9/25 19:20:02 163.4
主界面.html 2026/9/26 16:47:00  53.8
主程序.js   2026/9/26 16:47:11 512.8


=== 备份文件 ===

Name                                       LastWriteTime     
----                                       -------------     
主界面.html.bak-before-lazy2d-20260926-164506 2026/9/25 20:27:33
主程序.js.bak-before-lazy2d-20260926-164506   2026/9/25 20:45:05


=== HTML 差异（改动前 vs 现在）===
差异行数: 131
=> <!-- defer：音频引擎是 43 KB，不阻塞首屏渲染；defer 脚本按文档顺序执行，
=> 它在 <head> 里最靠前，所以仍会先于 主程序.js 跑完 —— 时序与原来一致。 -->
=> <script src="AbyssAudio.js?v=202609320" defer></script>
=> <!-- ===== 2D 引擎四件套已改为「按需加载」（见 </body> 前的加载器）=====
=> 原来这里顺序加载 phaser / 角色形象 / 战斗2D / 经典2D，共 1467 KB，
=> 而「开始界面 + 选英雄 + 选增益」这三步全由 主程序.js 自己渲染（它里面
=> Phaser 出现 0 次），根本用不到这四件套。
=> 改到按需加载后，首屏只剩下面这一个脚本，体积从 2587 KB 降到 417 KB。
=> defer：不阻塞 HTML 解析，星空开始界面立刻出现。
=> 它的启动逻辑本来就挂在 DOMContentLoaded（主程序.js 行 9987 / 12519），
=> 而 defer 脚本在 DOMContentLoaded 之前执行完，时序天然兼容。 -->
=> <script src="主程序.js?v=202610230" defer></script>
=> 
=> 
=> <!-- ===== 2D 引擎按需加载时的等待提示（阶段3优化新增）=====
=> 刻意**不复用** #trial2DBootHint：那个元素在 #trial2DStage 内部，而 stage 带
=> .hidden —— 在 经典2D.js 还没加载时它根本显示不出来，提示会看不见。
=> 这里复用 .trial2d-boot 的现成样式，只把定位从 absolute 改成 fixed。
=> 游戏原有的元素一个都没有改动。 -->
=> <div class="trial2d-boot hidden" id="lazy2DBootHint" style="position:fixed; z-index:9999;">
=> <div class="trial2d-boot-spinner"></div>
=> <div class="trial2d-boot-title">正在启动 2D 实时战斗…</div>
=> <div class="trial2d-boot-sub">首次进入需要下载 2D 战斗引擎（约 1.5 MB），下完就会缓存，之后再进不用等。</div>
=> </div>
=> 
=> <!-- ============================================================
=> 2D 引擎按需加载器（阶段3优化）
=> ------------------------------------------------------------
=> 首屏只加载「文字界面」所需的 主程序.js + 主样式.css + AbyssAudio.js
=> （合计 417 KB）。phaser / 角色形象 / 战斗2D / 经典2D 这四件套（1467 KB）
=> 推迟到玩家真正要玩时再下 —— 按 Netlify 实测的 30 KB/s 算，
=> 首屏从 22.5 秒降到约 4 秒。
=> 
=> ⚠️ 必须**串行**加载，不能并行：
=> 战斗2D.js 顶层写着 `class BattleScene extends Phaser.Scene`，
=> 这是脚本**解析时**就求值的 —— phaser.min.js 没先执行完，
=> 战斗2D.js 会直接抛 ReferenceError。所以下面用 reduce 串成一条链。
=> 
=> 接口（供 主程序.js 调用）：
=> __加载2D引擎()    → Promise；开始加载或复用进行中的加载
=> __2D引擎已就绪()  → boolean
=> __确保2D引擎(cb)  → 已就绪时**同步**回调（调用方行为与优化前一致）；
=> 未就绪时显示等待提示，加载完再回调；
=> 加载失败**也**回调 → 自动降级走文字界面，不会卡死。
=> ============================================================ -->
=> <script>
=> (function () {
=> 'use strict';
=> 
=> var FILES = [
=> 'vendor/phaser.min.js?v=20250907p',
=> '角色形象.js?v=20250910r2',
=> '战斗2D.js?v=202610210',
=> '经典2D.js?v=202610220'
=> ];
=> 
=> var 加载中 = null;        // 进行中的 Promise（复用，避免重复下载）
=> var 已就绪 = false;
=> 
=> function 提示(show) {
=> var el = document.getElementById('lazy2DBootHint');
=> if (!el) return;
=> el.classList.toggle('hidden', !show);
=> var sp = el.querySelector('.trial2d-boot-spinner');
=> if (sp) sp.style.animationPlayState = show ? 'running' : 'paused';
=> }
=> 
=> function 载入一个(src) {
=> return new Promise(function (resolve) {
=> var s = document.createElement('script');
=> s.src = src;
=> s.async = false;                 // 按插入顺序执行
=> s.onload = function () { resolve(true); };
=> s.onerror = function () {
=> console.error('[2D加载器] 脚本下载失败：' + src);
=> resolve(false);                // 不 reject：把控制权还给调用方去降级
=> };
=> document.head.appendChild(s);
=> });
=> }
=> 
=> window.__加载2D引擎 = function () {
=> if (加载中) return 加载中;
=> 加载中 = FILES.reduce(function (chain, src) {
=> return chain.then(function (ok) {
=> if (ok === false) return false;     // 前面已经挂了，后面不再硬试
=> return 载入一个(src);
=> });
=> }, Promise.resolve(true)).then(function (ok) {
=> 已就绪 = (ok !== false) && !!window.经典2D;
=> if (已就绪) {
=> console.log('[2D加载器] 2D 引擎就绪。');
=> } else {
=> 加载中 = null;                      // 允许以后重试
=> console.warn('[2D加载器] 2D 引擎未就绪，本次改用文字界面（功能不受影响）。');
=> }
=> return 已就绪;
