  // 让所有「动态插入的 <script src>」指向不存在的文件 → 模拟 2D 引擎加载失败
  const origCreate = Document.prototype.createElement;
  Document.prototype.createElement = function (tag) {
    const el = origCreate.call(this, tag);
    if (String(tag).toLowerCase() === 'script') {
      const d = Object.getOwnPropertyDescriptor(HTMLScriptElement.prototype, 'src');
      Object.defineProperty(el, 'src', {
        configurable: true,
        get() { return d.get.call(el); },
        set(v) { d.set.call(el, '故障注入-' + v); }
      });
    }
    return el;
  };
  return {
    拦截器已注入: true,
    注入前_引擎就绪: window.__2D引擎已就绪(),
    注入前_Phaser: typeof window.Phaser,
    注入前_已加载资源: performance.getEntriesByType('resource').map(e => decodeURIComponent(e.name.split('/').pop().split('?')[0]))
  };
})()"}

