{"script": "(async () => {
  const q = (s) => document.querySelector(s);
  const 日志 = [];

  document.getElementById('startGameBtn').click();
  await new Promise(r => setTimeout(r, 800));
  日志.push('点开始游戏后 → 事件标题=' + JSON.stringify(q('#eventTitle')?.textContent || ''));

  const hero = document.querySelector('#actionArea button[data-action="choose-hero"]');
  if (hero) { hero.click(); await new Promise(r => setTimeout(r, 400)); 日志.push('选英雄' + hero.textContent.trim() + ' → ' + JSON.stringify(q('#eventTitle')?.textContent || '')); }

  // 监听提示层出现
  const el = q('#lazy2DBootHint');
  let 提示曾显示 = false;
  const obs = new MutationObserver(() => { if (!el.classList.contains('hidden')) 提示曾显示 = true; });
  obs.observe(el, { attributes: true, attributeFilter: ['class'] });

  const bonus = document.querySelector('#actionArea button[data-action="choose-bonus"]');
  const 增益名 = bonus ? bonus.textContent.trim() : null;
  if (bonus) bonus.click();
  await new Promise(r => setTimeout(r, 3000));
  obs.disconnect();

  return {
    流程日志: 日志,
    选增益: 增益名,
    提示层曾显示: 提示曾显示,
    提示层现状态: el.className,
    引擎已就绪: window.__2D引擎已就绪(),
    Phaser: typeof window.Phaser,
    经典2D: typeof window.经典2D,
    body_class: document.body.className || '(无，即文字模式)',
    事件标题: q('#eventTitle') ? q('#eventTitle').textContent.trim() : '-',
    事件文本: q('#eventText') ? q('#eventText').textContent.trim().slice(0, 70) : '-',
    可选按钮: [...document.querySelectorAll('#actionArea button')].map(b => b.textContent.trim()).slice(0, 8),
    开始界面opacity: q('#startScreen') ? getComputedStyle(q('#startScreen')).opacity : '-',
    玩家血量: q('#playerHp') ? q('#playerHp').textContent.trim() : '-',
    动作区可见: q('#actionArea') ? getComputedStyle(q('#actionArea')).display : '-'
  };
})()"}

