{"script": "(async () => {
  const q = (s) => document.querySelector(s);
  document.getElementById('startGameBtn').click();
  // 读档 → 门控B → 引擎加载 → 进 2D
  for (let i = 0; i < 20; i++) {
    await new Promise(r => setTimeout(r, 300));
    if (window.__2D引擎已就绪() && window.经典2D && window.经典2D.active && window.经典2D.active()) break;
  }
  await new Promise(r => setTimeout(r, 1500));
  let d = null;
  try { d = window.战斗2D.debug(); } catch (e) { d = null; }
  return {
    引擎就绪: window.__2D引擎已就绪(),
    2D运行中: d ? d.running : null,
    英雄hp: d && d.hero ? d.hero.hp : null,
    楼层: d ? d.floor : null,
    房间: d && d.room ? d.room.type : null,
    debug里的hero字段: d && d.hero ? Object.keys(d.hero) : [],
    hero完整: d && d.hero ? JSON.stringify(d.hero).slice(0, 300) : null
  };
})()"}

